181	/** Parse YAML frontmatter from a SKILL.md file to extract the description. */
182	function parseSkillFrontmatter(markdown: string): { description: string } {
183	  const match = markdown.match(/^---\n([\s\S]*?)\n---/);
184	  if (!match) return { description: "" };
185	  const yaml = match[1];
186	  // Extract description — handles both single-line and multi-line YAML values
187	  const descMatch = yaml.match(
188	    /^description:\s*(?:>\s*\n((?:\s{2,}[^\n]*\n?)+)|[|]\s*\n((?:\s{2,}[^\n]*\n?)+)|["']?(.*?)["']?\s*$)/m
189	  );
190	  if (!descMatch) return { description: "" };
191	  const raw = descMatch[1] ?? descMatch[2] ?? descMatch[3] ?? "";
192	  return {
193	    description: raw
194	      .split("\n")
195	      .map((l: string) => l.trim())
196	      .filter(Boolean)
197	      .join(" ")
198	      .trim(),
199	  };
200	}
